(() => {
  const slideTitle = document.getElementById('slideTitle');
  const slideSubtitle = document.getElementById('slideSubtitle');
  const slideBody = document.getElementById('slideBody');
  const slideVisual = document.getElementById('slideVisual');
  const slideCounter = document.getElementById('slideCounter');
  const slideProgress = document.getElementById('slideProgress');
  const slideDots = document.getElementById('slideDots');
  const prevSlide = document.getElementById('prevSlide');
  const nextSlide = document.getElementById('nextSlide');
  let currentSlide = 0;

  const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));

  function flowItems(index) {
    const flows = {
      2: ['Pre-Production','Production','Post-Production'],
      4: ['Script / Synopsis','Storyboarding, Design & Audio','Animatic','Colour Styling & Sound Breakdown'],
      10: ['Traditional Animation','Paperless Animation','Cut-Out Animation'],
      12: ['Layout & Posing','Animation','Animation Clean Up','Ink & Paint','Compositing','Export & Render'],
      17: quizData.traditional.map(item => item.label),
      18: ['Review Presentation','Take Notes','Paperless Quiz','Traditional Quiz','Review PDF']
    };
    return flows[index] || [];
  }

  function renderSlide(index) {
    currentSlide = Math.max(0, Math.min(slides.length - 1, index));
    const slide = slides[currentSlide];
    slideTitle.textContent = slide.title;
    slideSubtitle.textContent = slide.subtitle;
    const paragraphs = slide.body.split(/\n\n+/).filter(Boolean);
    slideBody.innerHTML = paragraphs.map(p => `<p>${escapeHtml(p).replace(/\n/g,'<br>')}</p>`).join('');
    const flow = flowItems(currentSlide);
    slideVisual.innerHTML = flow.map(item => `<span class="flow-chip">${escapeHtml(item)}</span>`).join('');
    slideCounter.textContent = `Slide ${currentSlide + 1} of ${slides.length}`;
    slideProgress.style.width = `${((currentSlide + 1) / slides.length) * 100}%`;
    [...slideDots.children].forEach((dot, i) => dot.classList.toggle('active', i === currentSlide));
    prevSlide.disabled = currentSlide === 0;
    nextSlide.disabled = currentSlide === slides.length - 1;
  }

  slides.forEach((_, index) => {
    const dot = document.createElement('button');
    dot.type = 'button';
    dot.className = 'slide-dot';
    dot.setAttribute('aria-label', `Go to slide ${index + 1}`);
    dot.addEventListener('click', () => renderSlide(index));
    slideDots.append(dot);
  });
  prevSlide.addEventListener('click', () => renderSlide(currentSlide - 1));
  nextSlide.addEventListener('click', () => renderSlide(currentSlide + 1));
  document.addEventListener('keydown', event => {
    if (!document.getElementById('presentation').matches(':hover')) return;
    if (event.key === 'ArrowLeft') renderSlide(currentSlide - 1);
    if (event.key === 'ArrowRight') renderSlide(currentSlide + 1);
  });
  renderSlide(0);

  // Task checklist with local persistence.
  const checks = [...document.querySelectorAll('#lessonChecklist input[type="checkbox"]')];
  const taskText = document.getElementById('taskProgressText');
  const taskBar = document.getElementById('taskProgressBar');
  const storageKey = 'lesson2-animation-pipeline-progress';

  function saveTasks() {
    const state = Object.fromEntries(checks.map(c => [c.dataset.task, c.checked]));
    try { localStorage.setItem(storageKey, JSON.stringify(state)); } catch (e) {}
  }
  function loadTasks() {
    try {
      const state = JSON.parse(localStorage.getItem(storageKey) || '{}');
      checks.forEach(c => c.checked = Boolean(state[c.dataset.task]));
    } catch (e) {}
  }
  function updateTaskProgress() {
    const done = checks.filter(c => c.checked).length;
    taskText.textContent = `${done} of ${checks.length} complete`;
    taskBar.style.width = `${checks.length ? done / checks.length * 100 : 0}%`;
    saveTasks();
  }
  loadTasks();
  checks.forEach(c => c.addEventListener('change', updateTaskProgress));
  updateTaskProgress();

  // Sequencing quizzes.
  const listFor = key => document.getElementById(`${key}List`);
  const resultFor = key => document.getElementById(`${key}Result`);
  const scoreFor = key => document.getElementById(`${key}Score`);

  function shuffle(array) {
    const a = [...array];
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    if (a.every((item, i) => item.label === array[i].label) && a.length > 1) {
      [a[0], a[1]] = [a[1], a[0]];
    }
    return a;
  }

  function itemMarkup(item) {
    const li = document.createElement('li');
    li.className = 'sequence-item';
    li.draggable = true;
    li.dataset.label = item.label;
    li.innerHTML = `
      <span class="sequence-thumb"><img src="${item.img}" alt=""></span>
      <span class="sequence-label">${escapeHtml(item.label)}</span>
      <span class="sequence-controls">
        <button type="button" data-move="up" aria-label="Move ${escapeHtml(item.label)} up">↑</button>
        <button type="button" data-move="down" aria-label="Move ${escapeHtml(item.label)} down">↓</button>
      </span>`;
    return li;
  }

  function renderQuiz(key, items) {
    const list = listFor(key);
    list.innerHTML = '';
    items.forEach(item => list.append(itemMarkup(item)));
    resultFor(key).hidden = true;
    scoreFor(key).textContent = 'Not checked';
  }

  function currentLabels(key) {
    return [...listFor(key).querySelectorAll('.sequence-item')].map(li => li.dataset.label);
  }

  function markTask(task, value = true) {
    const input = checks.find(c => c.dataset.task === task);
    if (input) {
      input.checked = value;
      updateTaskProgress();
    }
  }

  function checkQuiz(key) {
    const correct = quizData[key].map(item => item.label);
    const actual = currentLabels(key);
    let matched = 0;
    actual.forEach((label, i) => { if (label === correct[i]) matched++; });
    const percent = Math.round(matched / correct.length * 100);
    const passed = matched === correct.length;
    const result = resultFor(key);
    result.hidden = false;
    result.className = `quiz-result ${passed ? 'pass' : 'fail'}`;
    result.innerHTML = passed
      ? `<strong>${matched}/${correct.length} — 100%</strong><br>Correct! The complete pipeline is in the right order.`
      : `<strong>${matched}/${correct.length} positions correct — ${percent}%</strong><br>Keep adjusting the order and check again.`;
    scoreFor(key).textContent = passed ? 'Complete' : `${percent}%`;
    if (passed) markTask(key, true);
  }

  document.querySelectorAll('[data-check]').forEach(button => {
    button.addEventListener('click', () => checkQuiz(button.dataset.check));
  });
  document.querySelectorAll('[data-shuffle]').forEach(button => {
    button.addEventListener('click', () => renderQuiz(button.dataset.shuffle, shuffle(quizData[button.dataset.shuffle])));
  });

  document.addEventListener('click', event => {
    const move = event.target.closest('[data-move]');
    if (!move) return;
    const item = move.closest('.sequence-item');
    const list = item.parentElement;
    if (move.dataset.move === 'up' && item.previousElementSibling) {
      list.insertBefore(item, item.previousElementSibling);
    } else if (move.dataset.move === 'down' && item.nextElementSibling) {
      list.insertBefore(item.nextElementSibling, item);
    }
  });

  let dragged = null;
  document.addEventListener('dragstart', event => {
    const item = event.target.closest('.sequence-item');
    if (!item) return;
    dragged = item;
    item.classList.add('dragging');
    event.dataTransfer.effectAllowed = 'move';
  });
  document.addEventListener('dragend', event => {
    const item = event.target.closest('.sequence-item');
    if (item) item.classList.remove('dragging');
    document.querySelectorAll('.drop-target').forEach(el => el.classList.remove('drop-target'));
    dragged = null;
  });
  document.addEventListener('dragover', event => {
    const target = event.target.closest('.sequence-item');
    if (!dragged || !target || dragged === target || dragged.parentElement !== target.parentElement) return;
    event.preventDefault();
    document.querySelectorAll('.drop-target').forEach(el => el.classList.remove('drop-target'));
    target.classList.add('drop-target');
  });
  document.addEventListener('drop', event => {
    const target = event.target.closest('.sequence-item');
    if (!dragged || !target || dragged === target || dragged.parentElement !== target.parentElement) return;
    event.preventDefault();
    const list = target.parentElement;
    const rect = target.getBoundingClientRect();
    const after = event.clientY > rect.top + rect.height / 2;
    list.insertBefore(dragged, after ? target.nextElementSibling : target);
    target.classList.remove('drop-target');
  });

  renderQuiz('paperless', shuffle(quizData.paperless));
  renderQuiz('traditional', shuffle(quizData.traditional));
})();
